#![cfg(target_os="linux")]
use std::{fs,path::PathBuf};
use ulmdb::{Environment,PublicationMode,PageSize,ResidencyPolicy,ReadAhead,DatabaseKind,ReadTxn,backup};
struct Dir(PathBuf);impl Dir{fn new()->Self{Self(std::env::temp_dir().join(format!("external-copy-{:032x}",ulmdb_storage::new_identity().unwrap())))}}impl Drop for Dir{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn absent(p:&std::path::Path){assert!(!p.join(".ulmdb-coordination").exists());assert!(!p.join("LMDB-WRITER").exists());}
#[test]fn external_pair_compact_and_genesis_preserve_actual_checkpoints_without_locks_or_pins(){for mode in [PublicationMode::Legacy,PublicationMode::Cohort,PublicationMode::Indexed]{let src=Dir::new();let pair_out=Dir::new();let compact=Dir::new();let empty=Dir::new();let e=Environment::create_externally_synchronized(&src.0,mode,PageSize::DEFAULT,ResidencyPolicy::Demand,ReadAhead::Normal,None,Default::default()).unwrap();let mut w=e.begin_write().unwrap();w.create_database(b"kv",DatabaseKind::Kv).unwrap();w.put(b"kv",b"k",b"A").unwrap();w.commit().unwrap();let a=e.begin_read();let a_cp=a.file_checkpoint().unwrap();let mut w=e.begin_write().unwrap();w.put(b"kv",b"k",b"B").unwrap();w.commit().unwrap();let b=e.begin_read();let authority=b.external_synchronization().unwrap();let b_cp=b.file_checkpoint().unwrap();let metadata=authority.capture_copy_pair(None).unwrap();assert_eq!(*metadata.selected_checkpoint(),b_cp);assert_eq!(metadata.predecessor_checkpoint().unwrap(),Some(a_cp));let pair=metadata.admit(ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();assert_eq!(pair.selected().get(b"kv",b"k").unwrap(),Some(b"B".as_slice()));assert_eq!(pair.predecessor().unwrap().get(b"kv",b"k").unwrap(),Some(b"A".as_slice()));let report=backup::export_file_pair(&pair,&pair_out.0).unwrap();assert_eq!(report.selected_checkpoint,b_cp);assert_eq!(report.predecessor_checkpoint,Some(a_cp));assert_eq!(ReadTxn::open_externally_synchronized(&pair_out.0).unwrap().get(b"kv",b"k").unwrap(),Some(b"B".as_slice()));
 let previous=authority.capture_copy_pair(None).unwrap().admit_view(true,ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();assert_eq!(*previous.view_checkpoint(),a_cp);let report=backup::compact_file_copy(&previous,&compact.0).unwrap();assert_eq!(report.selected.sequence,1);assert_eq!(ReadTxn::open_externally_synchronized(&compact.0).unwrap().get(b"kv",b"k").unwrap(),Some(b"A".as_slice()));backup::create_empty_file_copy_externally_synchronized(&empty.0,mode,PageSize::DEFAULT,None,Default::default()).unwrap();assert_eq!(ReadTxn::open_externally_synchronized(&empty.0).unwrap().sequence(),0);for p in [&src.0,&pair_out.0,&compact.0,&empty.0]{absent(p);}
 }}
#[test]fn external_copy_pair_keeps_historyless_normalization_and_namespace_refusal(){let src=Dir::new();let normalized=Dir::new();let e=Environment::create_externally_synchronized(&src.0,PublicationMode::Legacy,PageSize::DEFAULT,ResidencyPolicy::Demand,ReadAhead::Normal,None,Default::default()).unwrap();let mut w=e.begin_write().unwrap();w.create_database(b"kv",DatabaseKind::Kv).unwrap();w.put(b"kv",b"k",b"A").unwrap();w.commit().unwrap();let a=e.begin_read();let ctx=a.external_synchronization().unwrap();let genesis=ulmdb_storage::read_previous(&src.0).unwrap().unwrap();fs::remove_file(src.0.join("PREVIOUS")).unwrap();fs::remove_file(ulmdb_storage::descriptor_path(&src.0,&genesis)).unwrap();let pair=ctx.capture_copy_pair(None).unwrap().admit(ResidencyPolicy::Demand,ReadAhead::Normal,None).unwrap();let r=backup::export_file_pair(&pair,&normalized.0).unwrap();assert!(r.normalization.is_some());assert_eq!(r.selected.sequence,1);assert!(r.predecessor.is_none());assert_eq!(ReadTxn::open_externally_synchronized(&normalized.0).unwrap().get(b"kv",b"k").unwrap(),Some(b"A".as_slice()));absent(&normalized.0);
 let moved=src.0.with_extension("moved");fs::rename(&src.0,&moved).unwrap();fs::create_dir(&src.0).unwrap();let out=Dir::new();assert!(backup::export_file_pair(&pair,&out.0).is_err());assert!(!out.0.exists());drop(e);fs::remove_dir_all(moved).unwrap();}
